import{_ as t,o as a,c as n,a3 as i}from"./chunks/framework.BPaanrMb.js";const d=JSON.parse('{"title":"Community organization","description":"WheelOS technical steering, operations, contributors and collaboration model.","frontmatter":{"title":"Community organization","description":"WheelOS technical steering, operations, contributors and collaboration model.","status":"Repository fact","content_type":"organization","keywords":["WheelOS","open-source community","governance","collaboration"]},"headers":[],"relativePath":"en/organization/organization.md","filePath":"en/organization/organization.md","lastUpdated":1794551845000}'),o={name:"en/organization/organization.md"};function r(s,e,c,l,u,m){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="wheelos-open-source-community-structure" tabindex="-1">WheelOS open-source community structure <a class="header-anchor" href="#wheelos-open-source-community-structure" aria-label="Permalink to &quot;WheelOS open-source community structure&quot;">​</a></h1><h2 id="technical-steering-committee" tabindex="-1">Technical Steering Committee <a class="header-anchor" href="#technical-steering-committee" aria-label="Permalink to &quot;Technical Steering Committee&quot;">​</a></h2><ul><li><strong>Responsibilities:</strong> technical direction, code quality, release planning and technical decisions.</li><li><strong>Members:</strong> core contributors, module maintainers and senior technical experts.</li><li><strong>Working method:</strong> regular technical meetings, pull-request and issue review, and technical sharing with the community.</li></ul><h2 id="operations-committee" tabindex="-1">Operations Committee <a class="header-anchor" href="#operations-committee" aria-label="Permalink to &quot;Operations Committee&quot;">​</a></h2><ul><li><strong>Responsibilities:</strong> non-technical community operations including outreach, resource management and events.</li><li><strong>Members:</strong> community managers, designers, marketing specialists and active user representatives.</li><li><strong>Working method:</strong> plan hackathons and summits, promote projects, manage funding and sponsor relationships, and maintain collaboration tools such as Slack and forums.</li></ul><h2 id="contributors" tabindex="-1">Contributors <a class="header-anchor" href="#contributors" aria-label="Permalink to &quot;Contributors&quot;">​</a></h2><p>Contributors submit code, documentation, defect reports and optimization proposals; participate in technical decisions through proposals; and share experience through meetings and forums. Collaboration happens through GitHub, Slack and mailing lists.</p><h2 id="long-term-and-project-work" tabindex="-1">Long-term and project work <a class="header-anchor" href="#long-term-and-project-work" aria-label="Permalink to &quot;Long-term and project work&quot;">​</a></h2><ul><li>The Technical Committee maintains the roadmap and core codebase and runs technical reviews.</li><li>The Operations Committee runs events, updates communication channels and tracks community growth.</li><li>Project-based work prepares releases, implements major modules and runs user research and campaigns.</li></ul><h2 id="maintaining-technical-quality" tabindex="-1">Maintaining technical quality <a class="header-anchor" href="#maintaining-technical-quality" aria-label="Permalink to &quot;Maintaining technical quality&quot;">​</a></h2><ul><li>Publish code style, contribution and technical-decision processes.</li><li>Make meeting notes and discussions public.</li><li>Recognize core contributors.</li><li>Lower participation barriers through sharing sessions, courses and documentation.</li></ul><h2 id="community-outreach" tabindex="-1">Community outreach <a class="header-anchor" href="#community-outreach" aria-label="Permalink to &quot;Community outreach&quot;">​</a></h2><p>Use LinkedIn, YouTube and relevant regional channels for updates and tutorials; publish blogs, case studies and industry articles; run hackathons and meetups; participate in industry events; and collaborate with universities, companies and developer communities.</p>',13)])])}const p=t(o,[["render",r]]);export{d as __pageData,p as default};
